<style>
/* Bind the incumbent shell/classes to the existing V2 controls. */
html,body{height:auto;min-height:100%;overflow-x:clip}body{padding-left:76px;font-family:var(--font-sans);font-size:14px;line-height:1.5;background:var(--canvas);color:var(--text-main)}
.workspace-sidebar.app-sidebar{position:fixed;inset:0 auto 0 0;width:76px;min-width:76px;height:100dvh;padding:0;z-index:100;overflow-x:hidden;overflow-y:auto;scrollbar-width:none;background:#fff}
.workspace-sidebar .sidebar-brand{min-height:83px;padding:24px 18px 18px;display:flex;align-items:center;justify-content:flex-start;gap:12px;border-bottom:1px solid var(--border-subtle)}
.brand-mark{width:40px;height:40px;min-width:40px;display:flex;align-items:center;justify-content:center;background:var(--primary-hover);color:#fff;border-radius:12px;box-shadow:0 4px 12px rgb(45 106 79 / .18)}
.workspace-sidebar .sidebar-brand-text{width:164px;min-width:164px;opacity:0;transition:opacity .18s ease;white-space:nowrap}.workspace-sidebar .sidebar-brand strong{font-size:15px;color:var(--primary-hover);font-weight:800}.workspace-sidebar .sidebar-brand small{text-transform:uppercase;font-size:10.5px;letter-spacing:.08em;font-weight:700;color:var(--text-caption)}
.workspace-sidebar .nav.sidebar-nav{padding:20px 14px;gap:6px;flex:1;display:flex;flex-direction:column;margin:0}
.workspace-sidebar .nav a{min-height:44px;padding:9px 12px;border-radius:9px;font-size:13.5px;font-weight:500;color:var(--text-caption);justify-content:flex-start;gap:10px;min-width:48px;flex:none;white-space:nowrap}
.workspace-sidebar .nav a svg{width:18px;height:18px;min-width:18px;flex:0 0 18px;color:#64748b}.workspace-sidebar .nav a>span{opacity:0;white-space:nowrap;transition:opacity .18s ease}.workspace-sidebar .nav a[aria-selected=true]{background:rgb(45 106 79 / .08);color:var(--primary-hover);font-weight:600}.workspace-sidebar .nav a[aria-selected=true] svg{color:var(--primary-hover)}
.workspace-sidebar .sidebar-footer{padding:16px;border-top:1px solid var(--border-subtle);gap:10px;background:#fbfdfc;margin-top:auto}.sidebar-footer .role-label{display:none;font-size:12px}.sidebar-footer form{margin:0}.sidebar-footer button{width:44px;height:44px;padding:0;display:flex;align-items:center;justify-content:flex-start;gap:10px;overflow:hidden}.sidebar-footer button svg{min-width:18px;margin-left:12px}.sidebar-footer button span{opacity:0;white-space:nowrap}
.top.main-topbar{height:64px;min-height:64px;padding:0;z-index:90}.top>.wrap{max-width:none;width:100%;padding:14px 28px;gap:14px;margin:0}.top-context strong{font-family:var(--font-sans);font-size:22px;font-weight:700;color:var(--primary-hover);line-height:1.3;letter-spacing:-.02em}.top-context>span{display:none}.top .header-state{display:flex;align-items:center;gap:12px;font-size:12px;color:var(--text-caption);margin-left:auto}.top .header-state a{font-weight:600;text-decoration:none;min-height:44px;display:inline-flex;align-items:center}
main.wrap.main-content{padding:28px;max-width:none;width:100%;margin:0;min-width:0}.work-heading{display:none}body:not([data-active-task=kasir]) .work-heading{display:flex;margin:0 0 20px}.work-heading h2{font-size:22px}.work-heading p{font-size:13px}
.preview{margin:0 0 10px;padding:0;border:0;background:none;font-size:11px;line-height:1.5;color:var(--text-caption);max-width:none}.preview::before{content:'• ';color:var(--primary)}
#kasir{font:14px/1.5 var(--font-sans);color:var(--text-main);--pos-text-main:var(--text-main)}#kasir .monitor-grid{margin-bottom:18px}#kasir .dash-card{margin:0}#kasir .monitor-grid>.dash-card{border:1px solid var(--border-card);box-shadow:0 4px 20px -2px rgb(27 67 50 / .05)}#kasir .dash-label{color:var(--text-caption)}#kasir .sales-period-control button,#kasir .dash-toggle button{min-height:34px}#kasir .sales-period-control button{color:var(--text-caption);border:0;box-shadow:none}#kasir .sales-period-control button[aria-pressed=true]{background:var(--primary-hover);color:#fff;-webkit-text-fill-color:#fff}.sales-period-pill{display:none}
#kasir .pos-workspace{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;align-items:start}#kasir .card{padding:18px;margin:0;border-radius:16px;box-shadow:0 4px 20px -2px rgb(27 67 50 / .05);border:1px solid var(--border-card)}#kasir h2{font-size:18px;font-weight:700;color:var(--primary-hover);padding-bottom:14px;border-bottom:1px solid var(--border-subtle);margin:0 0 18px}#kasir #h-checkout{font-size:20px;border:0;margin-bottom:12px;padding:0}
#kasir .pos-search-wrapper{margin-bottom:18px}#kasir .pos-search-wrapper>label{font-size:13px;margin-bottom:6px;font-weight:600}#kasir .pos-search-box{border:2px solid var(--mint-border);padding:8px 14px;gap:10px;border-radius:12px;box-shadow:0 3px 10px rgb(27 67 50 / .06)}#kasir input#pos-product-search{min-height:42px;padding:8px 0;font:500 14.5px var(--font-sans);border:0;box-shadow:none;width:100%;flex:1}#kasir #product-search-status{font-size:11.5px;margin:5px 0 0;line-height:1.5}#kasir .search-kbd-hint{font-size:11px;display:inline-flex;border-radius:6px;background:#f3f4f6;padding:3px 8px;white-space:nowrap}
#kasir .catalog-filter-row{grid-template-columns:minmax(150px,1.3fr) minmax(130px,1fr) auto;gap:10px;align-items:end;margin-bottom:12px}#kasir .catalog-filter-row label{font-size:11px;font-weight:700;color:var(--text-caption);margin-bottom:5px}#kasir .catalog-filter-row select{font:13px var(--font-sans);border-color:var(--border-control);border-radius:9px;min-height:40px;padding:7px 10px}#kasir .catalog-filter-row button{min-height:40px;padding:7px 14px;font:600 12px var(--font-sans);border:1px solid var(--mint-border);background:var(--mint-surface);color:var(--primary-hover)}
#kasir .catalog-table-scroll{max-height:320px;border:0;border-radius:0;overflow:auto}#kasir #products-table{width:100%;min-width:0;table-layout:auto}#kasir #products-table th{font-size:10.5px;letter-spacing:.04em;padding:9px 8px;background:#f1f6f3;color:var(--text-caption);border-bottom:1px solid var(--border-subtle);white-space:nowrap;width:auto}#kasir #products-table td{padding:12px 8px;font-size:12.5px;border-bottom:1px solid var(--border-subtle);vertical-align:middle;overflow-wrap:anywhere}#kasir #products-table .sku-code{font:500 11.5px var(--font-mono);display:inline-block;background:#f3f4f6;border-radius:5px;padding:3px 5px;max-width:100%}#kasir .stock-badge{display:inline-flex;font-size:11px;font-weight:700;border-radius:6px;background:#f3f6f4;padding:3px 7px;color:var(--text-caption)}#kasir .stock-badge.in-stock{background:#dcfce7;color:#14532d}#kasir #products-table .money{font-size:12.5px;white-space:normal!important;text-align:right;padding-right:14px}#kasir .btn-table-action{font:600 12px var(--font-sans);background:var(--mint-surface);color:var(--primary-hover);border:1px solid var(--mint-border);padding:7px 12px;border-radius:9999px;min-height:44px}
#kasir .cart-label{display:flex;justify-content:space-between;gap:8px;margin-bottom:6px}#kasir .cart-label strong{font-size:11px;font-weight:700;letter-spacing:.05em;color:var(--text-caption);text-transform:uppercase}#kasir .cart-label span{font-size:11.5px;color:var(--text-caption)}#kasir .cart-empty-message{background:#fafcfb;border-radius:10px;padding:28px 18px;text-align:center;font-size:12.5px;margin:0;max-width:none;color:var(--text-caption)}#kasir .cart-table-scroll{max-height:340px}#kasir .item-row{padding:14px 0;border-bottom:1px solid var(--border-subtle);gap:6px 10px}#kasir .cart-product-title{font-size:13px}#kasir .cart-product-meta{font-size:11px}#kasir .qty-stepper button[data-step]{border-radius:9px;color:var(--primary-hover);background:var(--mint-surface);border-color:var(--border-control);min-height:36px;height:36px}#kasir .qty-stepper input[data-name=quantity]{min-height:36px;height:36px;font-size:13px;width:68px;max-width:68px}#kasir .item-subtotal{font-size:13px;color:var(--primary-hover)}#kasir .line-discount>summary{font-size:11.5px;min-height:32px;padding:4px 0}#kasir .summary-box{background:var(--mint-surface);border:1px solid var(--mint-border);border-radius:16px;padding:12px 14px;margin-top:10px}#kasir .summary-total{border-top:2px solid var(--primary-hover);margin-top:10px;padding-top:10px;font-size:14px;color:var(--primary-hover)}#kasir #display-total{font-size:23px;font-weight:800;color:var(--primary-hover)}#kasir button#open-payment{background:var(--primary);min-height:48px;font:700 14.5px var(--font-sans);padding:12px 24px;border-radius:9999px;box-shadow:0 4px 12px rgb(45 106 79 / .15)}
#kasir .input-dialog{width:min(520px,calc(100vw - 32px));max-width:min(520px,calc(100vw - 32px));border-radius:18px;box-shadow:0 24px 60px rgb(0 0 0 / .25);border:1px solid var(--border-card);font:14px/1.5 var(--font-sans);max-height:calc(100dvh - 48px)}#kasir .popup-heading{padding:24px 24px 14px;border:0;align-items:center}#kasir .popup-heading h2{font-size:16px;font-weight:800;border:0;padding:0;margin:0}#kasir .popup-content{padding:0 24px 16px}#kasir .popup-footer{padding:0 24px 24px;border:0;gap:10px;flex-wrap:wrap}#kasir .popup-footer button{font:600 12px var(--font-sans);padding:8px 18px;border-radius:999px;min-height:44px}#kasir .popup-close{width:36px;min-width:36px;height:36px;min-height:36px;background:#f3f4f6;border-color:#e5e7eb;border-radius:9px;padding:0}#kasir .input-dialog .field{margin-bottom:12px}#kasir .input-dialog .row{gap:12px;margin:0 0 12px}#kasir .input-dialog .row>.field{margin:0;flex:1 1 150px}#kasir .input-dialog label{font-size:12px;margin-bottom:6px;color:var(--text-caption)}#kasir .input-dialog input,#kasir .input-dialog select{font:13.5px var(--font-sans);border:1px solid var(--border-control);border-radius:9px;min-height:44px;padding:9px 12px}#kasir .input-dialog .summary-box{margin:0 0 14px;padding:12px 14px;border-radius:12px}#kasir .input-dialog .summary-row{margin:0;font-size:13px}#kasir .input-dialog .note{font-size:11.5px;line-height:1.55;margin:6px 0 12px}#kasir .checkout-options{margin-top:12px}#kasir .checkout-options>summary{font-size:12px;min-height:40px}
#panel-kasir>#kasir{border:0;padding:0;background:none;box-shadow:none;margin:0}#panel-kasir>section[aria-labelledby=h-sales]{padding:24px;margin-top:18px}#panel-kasir>section[aria-labelledby=h-sales]>h2{font-size:18px;border-bottom:1px solid var(--border-subtle);padding-bottom:16px;margin-bottom:18px;color:var(--primary-hover)}#panel-kasir>section[aria-labelledby=h-sales] table{font-size:12.5px}.card[aria-labelledby=h-sales] td,.card[aria-labelledby=h-sales] th{padding:12px}
body.sidebar-pinned{padding-left:260px}.workspace-sidebar.app-sidebar.pinned{width:260px;min-width:260px}.workspace-sidebar.pinned .sidebar-brand-text,.workspace-sidebar.pinned .nav a>span,.workspace-sidebar.pinned .sidebar-footer button span{opacity:1}.workspace-sidebar.pinned .role-label{display:block}.workspace-sidebar.pinned .sidebar-footer button{width:100%}
@media(min-width:901px){.workspace-sidebar:focus-within{width:260px;min-width:260px}.workspace-sidebar:focus-within .sidebar-brand-text,.workspace-sidebar:focus-within .nav a>span{opacity:1}}
@media(hover:hover) and (min-width:901px){.workspace-sidebar.app-sidebar.collapsed:hover{width:260px;min-width:260px}.workspace-sidebar:hover .sidebar-brand-text,.workspace-sidebar:hover .nav a>span,.workspace-sidebar:hover .sidebar-footer button span{opacity:1}.workspace-sidebar:hover .sidebar-footer button{width:100%}}
@media(max-width:1100px){#kasir .catalog-filter-row{grid-template-columns:repeat(2,minmax(0,1fr))}#kasir .catalog-filter-row>button{grid-column:1/-1}}
@media(max-width:900px){body,body.sidebar-pinned{padding-left:0}.workspace-sidebar.app-sidebar{width:260px;min-width:260px;transform:translateX(-100%)}body.sidebar-open .workspace-sidebar{transform:none}.workspace-sidebar .sidebar-brand-text,.workspace-sidebar .nav a>span,.workspace-sidebar .sidebar-footer button span{opacity:1}.workspace-sidebar .sidebar-close{display:flex;position:absolute;right:8px;top:16px}.workspace-sidebar .sidebar-brand{padding-inline:14px;gap:8px}.workspace-sidebar .brand-mark{display:none}.workspace-sidebar .sidebar-brand-text{min-width:180px}.workspace-sidebar .sidebar-footer button{width:100%}.top>.wrap{padding:12px 18px}.top-context strong{font-size:18px}.top .header-state>span{display:none}.top .header-state{font-size:11px}.main-content.wrap{padding:18px}#kasir .pos-workspace{display:grid;grid-template-columns:1fr}#kasir .monitor-grid{display:block}#kasir .monitor-grid>.dash-card{margin-bottom:12px}#kasir #products-table{min-width:560px}#kasir .catalog-table-scroll{max-height:260px}#kasir .cart-table-scroll{max-height:260px}#kasir .catalog-filter-row{grid-template-columns:repeat(2,minmax(0,1fr))}#kasir .catalog-filter-row>button{grid-column:1/-1}#kasir .input-dialog .row>.field{flex:1 1 100%}#kasir .input-dialog input,#kasir .input-dialog select{font-size:16px}#kasir .search-kbd-hint{display:none}#kasir .input-dialog{max-height:calc(100dvh - 24px);width:calc(100vw - 24px);max-width:calc(100vw - 24px)}#kasir .popup-heading{padding:20px 20px 12px}#kasir .popup-content{padding:0 20px 14px}#kasir .popup-footer{padding:0 20px 20px}#kasir .popup-footer button{flex:1 1 auto}}
[hidden]{display:none!important}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:2px solid var(--primary-hover);outline-offset:3px}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}
</style>
